// Convert temperatures to integers (e.g., 725 for 72.5)
// Calculate total and average
// Print result with one decimal place

problem.solution:
int temp1 = 725; // 72.5°F
int temp2 = 812; // 81.2°F
int temp3 = 758; // 75.8°F
int total = temp1 + temp2 + temp3;
double average = total / 3.0 / 10;
System.out.println("Average: " + average); // Prints 76.5
